// === Tab: mySketch ===
// Attractor_10.0

let A = 50 ; let CZ = 100 ; let KL = 100 ; let K = 0.01 ; 
let dPXmin = 0.00001 ; let KdPX = 0.1 ; let PXmin = -150 ; let PXmax = 0 ; let dT = 0.01 ;

let PX ; let PY ; let T ; let Tmax ; let X ; let Y ; let Z ; 
let dPX ; let Q ; let Qmax ; let L ; let F ; let BX ; let BY ; long MLS ; let I ;
let lapse = 120;

function setup(){
  createCanvas(1112, 834) ; /*noSmooth() */; background(0) ; fill(0,0,0,20) ; stroke(255) ;
  dPX = KdPX ; PX = PXmin ; PY = 0 ; X = PX ; Y = PY ; BX = X ; BY = Y ; 
	strokeWeight(2);
}//setup()

function draw(){

  if ( I == 0 ){
    for ( Q = 0 ; Q < Qmax ; Q++ ){
      for( T = 0 ; T < Tmax ; T = T + dT ){
        Z = A*sin(T)+CZ ;
        L = sqrt((X*X)+(Z*Z)) ;
        F = (L-KL)*K ;
        Y = Y - (F*X/L) ;
        X = X + Y ; 
      }
      point(+X*4+width/2,+Y*40+height/2) ; point(-X*4+width/2,-Y*40+height/2) ;
      L = sqrt(pow(X-BX,2)+pow(Y-BY,2)) ;
      if ( L > 0 ){ dPX = dPX/L*KdPX ; }
      if ( dPX < dPXmin ){ dPX = dPXmin ; }

      PX = PX + dPX ; PY = 0 ;      
      BX = X ; BY = Y ; X = PX ; Y = PY ;
      if ( PX > PXmax || mousePressed ){ Q = Qmax ; I = 1 ; }
    }// Q 

    if ( millis() - MLS > 20 && Qmax > 1 ){ Qmax = Qmax - 1 ; }else{ Qmax = Qmax + 1 ; }
    MLS = millis() ; 

  }// I == 0

  if ( I > 0 ){
    //rect(-1,-1,width + 1,height+1) ; 
		I = I + 1 ;
    if ( I > 100 ){ 
      I = 0 ;  Tmax = Tmax + 0.5 ;
      PX = PXmin ; PY = 0 ; dPX = KdPX ; X = PX ; Y = PY ;
      background(0);
    }
  }// I > 0

} // draw()

function mousePressed(){
// prevents mouse press from registering twice
  if (frameCount - lapse > 15){
    save('pix.jpg');
    lapse = frameCount;
  }
}

